import {diagnosticFor,diagnosisFault,DIAGNOSIS_SOURCES,DIAGNOSIS_ACTIONS,DIAGNOSIS_REPAIR_MS} from './activation-diagnosis.mjs?v=1.2.0';
import {shuffleOptions} from './option-order.mjs?v=1.2.0';
import {ShiftSession,portrait} from './shift-session.mjs?v=1.2.0';
import {challengeFor} from './activation-checks.mjs?v=1.2.0';
import {installationEffects,reactiveLine} from './career-core.mjs?v=1.2.0';
import {createActivation,restoreActivation,applyActivationAction,advanceActivation,taskFor,buttonsFor,COMMANDS,PRESSURE,PRESSURE_INTERVAL,BEAR_LINES,locationText,credentialsText,POSITION_DELAY} from './activation-core.mjs?v=1.2.0';
import {equipmentPhoto,installationPhoto,mapSvg,vehiclePoint,phaseName} from './activation-visuals.mjs?v=1.2.0';
import {LOCATIONS} from './lt32-core.mjs?v=1.2.0';
const app=document.querySelector('#activation-app'),modal=document.querySelector('#activation-modal');
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let desk=null,state=null,context=null,selectedCommand=null,tickId=0,lastTick=0,seen=0,lastPressure=0,toastTimer=0,noticeTimer=0,failureTimer=0,focusBefore=null;
const tell=(event,payload={})=>{if(parent!==window)parent.postMessage({type:'andersons-activation',event,payload},location.origin);};
const solo=()=>['activation-free','lt32-free'].includes(context?.mode);
const saveKey=()=>solo()?'andersons-activation-solo-v1':'andersons-activation-campaign-v1';
function save(){if(state&&state.phase!=='failed')try{localStorage.setItem(saveKey(),JSON.stringify(state));}catch{}}
const audio={ctx:null,play(kind='tick'){if(context?.prefs?.sound===false||document.hidden)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{});const now=this.ctx.currentTime,notes=kind==='success'?[392,494,659,784]:kind==='fail'?[170,110]:kind==='message'?[800,1050]:[650];notes.forEach((n,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=now+i*.1;o.type=kind==='fail'?'triangle':'sine';o.frequency.value=n;g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+.22);});}catch{}}};
function toast(message){const el=$('#activation-toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700);}
const elapsed=()=>`${String(Math.floor(state.elapsedMs/60000)).padStart(2,'0')}:${String(Math.floor(state.elapsedMs/1000)%60).padStart(2,'0')}`;
const notifications=()=>Math.floor(state.elapsedMs/(desk?.profile.notificationMs||PRESSURE_INTERVAL));
function supervisor(){const intro=state.phase==='imei',done=state.phase==='finish';return `<section class="supervisor ${intro?'cat-supervisor':''}">${portrait(intro?'cat':'bear',done?'happy':'calm')}<div><span class="eyebrow">${intro?'CAT / PASSAGEM DE TURNO':done?'BEAR / APROVADO':'BEAR / SUPERVISÃO DA ATIVAÇÃO'}</span><strong id="bear-line">${intro?'INSTALOU? AGORA PRECISA ATIVAR.':done?'ISSO! RÁPIDO, EFICIENTE E SEM ERRAR!':BEAR_LINES[Math.floor(state.elapsedMs/7000)%BEAR_LINES.length]}</strong><p>${intro?'Confira as fotos do técnico. O IMEI precisa ser digitado.':done?'Pode respirar, Anderson. Até o próximo cliente.':'Faz certo e faz rápido. Eu estou acompanhando cada etapa.'}</p></div></section>`;}
function shell(content){return `<header class="act-topbar"><a class="brand" href="./" data-action="menu"><b>A</b> OS ANDERSONS</a><span class="top-caption">CENTRAL / INSTALAÇÃO E ATIVAÇÃO</span><nav><button data-action="sound">${context.prefs?.sound===false?'Som desligado':'Som ligado'}</button><button data-action="help">Guia rápido</button><button data-action="menu">${solo()||state.phase==='finish'?'Voltar ao início':'Salvar e sair'}</button></nav></header><main class="activation-main">${desk?.markup(state.phase)||''}<header class="chapter"><div><span class="chapter-number">03</span><div><span class="eyebrow">${state.phase==='finish'?'EXPEDIENTE CONCLUÍDO':'O EXPEDIENTE AINDA NÃO ACABOU'}</span><h1>ATIVAÇÃO</h1></div></div><div class="workload"><span><i class="live-dot"></i> <b id="current-phase">${phaseName(state)}</b></span><span>TEMPO <b id="elapsed">${elapsed()}</b></span><span>CHAMADOS <b id="notification-total">${notifications()}</b></span></div></header><div class="act-progress" aria-label="Progresso da ativação">${['IMEI','20 validações','Posição','Acesso','Concluído'].map((text,i)=>{const n=({imei:0,maze:1,platform:2,diagnosis:2,repairing:2,location:2,handoff:3,credentials:3,finish:4}[state.phase]);return `<span class="${n===i?'current':n>i?'done':''}"><b>${n>i?'✓':i+1}</b>${text}</span>`;}).join('')}</div>${state.phase==='finish'?finishView():`<div class="activation-grid"><section class="system-area">${content}</section><aside class="comms">${supervisor()}${chatPanel()}</aside></div>`}<footer class="act-footer"><span>OS ANDERSONS · ATO 03</span><span>Ambiente fictício · Nenhum comando ou mensagem é enviado para fora do jogo.</span></footer></main>`;}
function erpHeader(name='ANDERSON ERP',path='Operações / Ativação'){return `<header class="erp-top"><div><span class="erp-icon">A</span><strong>${name}</strong><small>ANDERSON · OPERADOR</small></div><span class="window-dots">● ● ●</span></header><div class="erp-breadcrumb"><span>${path}</span><span>SESSÃO #${state.imei.slice(-4)}</span></div>`;}
function imeiView(){return `<article class="system-card intake-system">${erpHeader()}<div class="system-tabs"><span class="active">01 · Identificação</span><span>Cadastro</span><span>Testes</span><span>Histórico</span></div><div class="imei-content"><span class="eyebrow">PRIMEIRO CAMPO / EQUIPAMENTO</span><h2>Qual aparelho foi instalado?</h2><p>Anderson enviou duas fotos no WhatsApp: a etiqueta e o local da instalação. Leia o <strong>IMEI do equipamento</strong> e digite os 15 números abaixo.</p><button class="mobile-label" data-action="photo-equipment" aria-label="Ampliar etiqueta recebida do técnico">${equipmentPhoto(state)}<span>Foto recebida do técnico · ampliar ↗</span></button><form id="imei-form" autocomplete="off"><label for="imei">IMEI do rastreador <span>15 dígitos</span></label><input id="imei" name="imei" type="text" inputmode="numeric" maxlength="15" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="Digite os números da etiqueta" value="${esc(state.imeiDraft)}"><small class="input-note">Digitação manual. Colar e arrastar texto não estão disponíveis neste campo.</small><div class="equipment-summary"><span>MODELO <b>LT-32 PRO</b></span><span>VEÍCULO <b>${esc(state.vehicle)}</b></span><span>TITULAR <b>${esc(state.client)}</b></span></div><button class="action-primary" type="submit">Conferir IMEI e iniciar ativação →</button></form><p class="quiet-note">A etiqueta também tem S/N e ICCID. O primeiro campo pede o IMEI.</p></div></article>`;}
function workflowView(){const task=taskFor(state),index=state.phase==='maze'?state.mazeStep:state.accessStep,total=state.phase==='maze'?20:6,skin=(index+(state.seed%4))%4,buttons=buttonsFor(state);return `<article class="system-card workflow skin-${skin}" data-screen="${skin}">${erpHeader(['ANDERSON ERP','PORTAL DE SERVIÇOS','CENTRAL PRO','ATIVAÇÃO LEGACY'][skin],state.phase==='maze'?'Equipamentos / Testes / Validação':'Clientes / Permissões / Acesso')}<div class="system-tabs">${['Operações','Pendências','Equipamentos','Validação','Clientes'].map((v,i)=>`<span class="${i===index%5?'active':''}">${v}</span>`).join('')}</div><div class="task-order"><span class="step-ticket">${String(index+1).padStart(2,'0')}<small>/${total}</small></span><div><span class="eyebrow">ORDEM DO BEAR / FAÇA AGORA</span><h2 id="task-title" tabindex="-1">${task.label}</h2><p>${task.instruction}</p></div></div><div class="system-noise" aria-hidden="true"><span>PROTOCOLO ${state.imei.slice(-6)}-${index+1}</span><span>${index%2?'CONFIGURAÇÃO VINCULADA':'CADASTRO EM VALIDAÇÃO'}</span><span>FILIAL ANDERSONS</span></div>${challengeMarkup()}<div class="action-board board-${skin}" aria-label="Funções disponíveis">${buttons.map((b,i)=>`<button class="workflow-action slot-${i}" ${challengeFor(state)&&!challengeFor(state).solved?'disabled':''} data-action="workflow" data-id="${b.id}"><small>${String((state.seed+i*31+index*7)%900+100)} / ${['ROTINA','SISTEMA','CADASTRO','FERRAMENTAS'][(i+index)%4]}</small><strong>${b.label}</strong><span aria-hidden="true">↗</span></button>`).join('')}</div><div class="workflow-foot"><span>Procedimento ${index+1} de ${total} · ${state.phase==='maze'?'testes e ativação':'liberação de acesso'}</span><span>Concluídos <b>${index}</b></span></div></article>`;}
function platformView(){const ready=state.gpsReady,waiting=state.commandSent&&!ready,evidence=diagnosticFor(state),repaired=diagnosisFault(state)!=='none'&&state.diagnosis.resolved;return `<article class="system-card platform">${erpHeader('ANDERSON TRACK','Monitoramento / Posições / Veículos')}<div class="monitor-toolbar"><div><strong>${esc(state.vehicle)}</strong><small>LT-32 PRO · ${state.imei}</small></div><span id="gps-status" class="gps-status ${ready?'green':''}"><i></i>${ready?'POSICIONADO':waiting?'COMANDO ENVIADO':'SEM POSIÇÃO'}</span></div><div id="map-slot">${mapSvg(state)}</div><div class="installation-effect">Sinal herdado da instalação: <strong>${installationEffects(context.installation).signal}%</strong> · aquisição normal em cerca de ${Math.round((state.positionDelay||18000)/1000)} s após um comando válido. Inconsistências abrem uma conferência antes da liberação.</div><div class="platform-data"><span>GSM <b>${state.commandSent?evidence.gsm:'AGUARDANDO'}</b></span><span>GPS <b>${ready?'FIX VÁLIDO':'SEM FIX'}</b></span><span>IGNIÇÃO <b>DESLIGADA</b></span><span>ALIMENTAÇÃO ATUAL <b>${evidence.external}</b></span></div>${state.diagnosis.action&&state.diagnosis.resolved?`<div class="diagnostic-receipt" role="status"><strong>✓ Conferência atualizada</strong><p>${esc(ready?evidence.receipt.replace('Solicite uma nova posição.','A nova posição foi recebida.'):evidence.receipt)}</p></div>`:''}${ready?`<section class="position-result"><span class="eyebrow">POSIÇÃO RECEBIDA / VÁLIDA</span><h2>Ficou verde. Envie ao técnico.</h2><p>${state.address}<br><code>${state.coordinates}</code></p><button class="action-primary" data-action="copy-location">${state.clipboard?.kind==='location'?'✓ Localização copiada':'Copiar localização'}</button><small>Abra Anderson · Técnico, cole e envie a localização recebida.</small></section>`:waiting?`<section class="waiting-position" role="status"><div class="signal-spinner"></div><div><strong>Aguardando o LT-32 PRO posicionar…</strong><p>Comando aceito. Aguarde a aquisição ou confira os indicadores. Uma falha não desaparece por reenviar o comando.</p><small id="position-wait">Recebendo posição · ${Math.floor(state.waitMs/1000)} s</small>${!repaired?'<button class="diagnostic-open" data-action="open-diagnosis">Conferir cadastro, laudo e telemetria →</button>':''}</div></section>`:`<section class="command-panel"><span class="eyebrow">TESTE O EQUIPAMENTO / ENVIE UM COMANDO</span><h2>Peça a posição atual do veículo.</h2><div class="commands">${shuffleOptions(COMMANDS,state.caseId,'activation.commands').map(c=>`<button class="command-option ${selectedCommand===c.id?'selected':''}" data-action="select-command" data-id="${c.id}" aria-pressed="${selectedCommand===c.id}">${c.label}</button>`).join('')}</div><button class="action-primary" data-action="send-command" ${!selectedCommand?'disabled':''}>Enviar comando selecionado →</button></section>`}</article>`;}
function diagnosisView(){const evidence=diagnosticFor(state),d=state.diagnosis,source=evidence.sources[d.tab];return `<article class="system-card diagnostic-system">${erpHeader('CENTRAL DE CONFERÊNCIAS','Primeira posição / Diagnóstico simulado')}<div class="diagnostic-heading"><span class="eyebrow">CRUZE AS INFORMAÇÕES ANTES DE AGIR</span><h2 id="diagnostic-title" tabindex="-1">Ainda não ficou verde. Por quê?</h2><p>Compare o cadastro, o laudo inicial e a leitura atual. Visite os três quadros e escolha uma conduta. Aguardar também pode ser correto quando os indicadores conferem.</p><span class="diagnostic-count">Quadros conferidos: ${d.reviewed.length} / 3</span></div><div class="diagnostic-tabs" role="tablist" aria-label="Fontes do diagnóstico">${DIAGNOSIS_SOURCES.map(source=>`<button role="tab" aria-selected="${d.tab===source.id}" aria-controls="diagnostic-evidence" data-action="inspect-diagnostic" data-id="${source.id}" class="${d.tab===source.id?'active':''}">${d.reviewed.includes(source.id)?'✓ ':''}${source.name}</button>`).join('')}</div><section class="diagnostic-evidence" id="diagnostic-evidence" role="tabpanel" aria-label="${source.title}"><h3>${source.title}</h3><dl>${source.rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p>${esc(source.note)}</p></section>${desk?.profile.id==='training'?`<div class="diagnostic-hint"><strong>Dica do estágio</strong><p>${esc(evidence.hint)}</p></div>`:''}<section class="diagnostic-decision"><h3>Qual conduta combina com os três quadros?</h3><p>${d.reviewed.length===3?'Escolha pela evidência, não pela pressa do Bear.':'Abra os três quadros para liberar as condutas.'}</p><div class="diagnostic-actions">${evidence.actions.map(a=>`<button data-action="resolve-diagnosis" data-id="${a.id}" ${d.reviewed.length===3?'':'disabled'}>${esc(a.label)}</button>`).join('')}</div></section><p class="diagnostic-fiction">Dados de bancada fictícios desta partida. Nenhum procedimento é enviado a equipamento real.</p></article>`;}
function repairingView(){const action=DIAGNOSIS_ACTIONS.find(a=>a.id===state.diagnosis.action);return `<article class="system-card diagnostic-system">${erpHeader('CENTRAL DE CONFERÊNCIAS','Correção / Atualização dos indicadores')}<section class="diagnostic-heading" role="status"><span class="eyebrow">CONDUTA REGISTRADA</span><h2 id="diagnostic-title" tabindex="-1">Aguarde a confirmação.</h2><p>${esc(action.label)}.</p><p>A conferência está sendo atualizada. Depois da confirmação, envie uma nova solicitação de posição.</p><progress id="diagnostic-repair-progress" max="${DIAGNOSIS_REPAIR_MS}" value="${state.diagnosis.repairMs}" aria-label="Confirmação da correção"></progress><small id="diagnostic-repair-time">Aguardando atualização…</small></section></article>`;}
function credentialsView(){return `<article class="system-card credentials">${erpHeader('ACESSOS / ANDERSONS','Cliente / Credenciais / Compartilhamento')}<div class="task-order"><span class="step-ticket">✓</span><div><span class="eyebrow">ACESSO GERADO</span><h2>Agora mande para o cliente.</h2><p>Confira o contato: o acesso é do cliente Anderson.</p></div></div><div class="access-card"><div class="access-title"><span>A</span><div><strong>${esc(state.client)}</strong><small>${esc(state.vehicle)} · Consulta de rastreamento</small></div></div><dl><div><dt>LOGIN</dt><dd>${state.login}</dd></div><div><dt>SENHA PROVISÓRIA</dt><dd>${state.password}</dd></div></dl><button class="action-primary" data-action="copy-credentials">${state.clipboard?.kind==='credentials'?'✓ Login e senha copiados':'Copiar login e senha'}</button><p>Abra Anderson · Cliente no WhatsApp, cole a mensagem e envie.</p></div><div class="access-warning">Técnico ≠ cliente. Os dois se chamam Anderson. Veja o contato.</div></article>`;}
const bubble=(text,own=false,name='')=>`<div class="chat-bubble ${own?'own':''}">${name?`<strong>${name}</strong>`:''}<p>${esc(text).replace(/\n/g,'<br>')}</p><small>${own?'enviado ✓✓':'agora'}</small></div>`;
function messages(){if(state.chatTarget==='client'){return bubble('Olá, Anderson! Já posso acompanhar meu carro?','', 'Anderson · Cliente')+(state.accessSent?bubble(credentialsText(state),true)+bubble('Recebi o acesso e entrei! Muito obrigado, Anderson.','', 'Anderson · Cliente'):'');}let html=bubble('Anderson, instalação feita! Seguem a etiqueta e o ponto onde escondi o LT-32 PRO. Confere o IMEI e faz a ativação pra mim.','', 'Anderson · Técnico');if(state.phase==='imei')html+=`<button class="chat-photo" data-action="photo-equipment" aria-label="Ampliar foto da etiqueta do LT-32 PRO">${equipmentPhoto(state)}<span>Etiqueta do equipamento · ampliar ↗</span></button><button class="chat-photo" data-action="photo-installation" aria-label="Ampliar foto do local de instalação">${installationPhoto(state)}<span>${LOCATIONS.find(l=>l.id===state.installationLocation).name} · ampliar ↗</span></button>`;else html+=`<button class="photo-shortcut" data-action="photo-equipment">▧ Ver foto da etiqueta</button><button class="photo-shortcut" data-action="photo-installation">▧ Ver local da instalação</button>`;if(state.phase!=='finish'){const n=notifications();for(let i=Math.max(0,n-4);i<n;i++)html+=bubble(PRESSURE[i%PRESSURE.length],false,'Anderson · Técnico');}if(['diagnosis','repairing'].includes(state.phase))html+=bubble('O laudo é do teste inicial. A leitura atual chegou depois da sincronização e da movimentação do veículo. Confira os três quadros antes de decidir.',false,'Anderson · Técnico');if(state.diagnosis.action&&state.diagnosis.resolved)html+=bubble(diagnosticFor(state).receipt,false,'Anderson · Técnico');if(state.locationSent)html+=bubble(locationText(state),true)+bubble('Posição recebida! Testes conferidos. Agora manda o login e a senha para o CLIENTE.','', 'Anderson · Técnico');if(state.phase==='finish')html+=bubble('Ativação concluída! Obrigado, Anderson. Cliente liberado e partindo.','', 'Anderson · Técnico');return html;}
function chatPanel(){const allowed=['location','credentials'].includes(state.phase),tech=state.chatTarget==='tech';return `<section class="activation-chat" aria-label="WhatsApp corporativo"><header class="whatsapp-title"><span>◉ WHATSAPP CORPORATIVO</span><b id="chat-unread">${Math.max(0,notifications()-seen)}</b></header><div class="contact-tabs">${shuffleOptions(['tech','client'],state.caseId,'activation.contacts').map(id=>`<button class="${state.chatTarget===id?'active':''}" data-action="contact" data-id="${id}">Anderson · ${id==='tech'?'Técnico':'Cliente'}</button>`).join('')}</div><div class="chat-person"><span class="contact-avatar">A</span><div><strong>Anderson · ${tech?'Técnico':'Cliente'}</strong><small>${tech?'na oficina · aguardando liberação':'aguardando acesso ao aplicativo'}</small></div></div><div id="activation-messages" class="activation-messages" role="log" aria-label="Conversa com ${tech?'o técnico':'o cliente'}">${messages()}</div><div class="compose"><label for="chat-draft">Mensagem para ${tech?'o técnico':'o cliente'}</label><textarea id="chat-draft" maxlength="800" rows="3" ${allowed?'':'disabled'} placeholder="${allowed?'Cole a informação correta antes de enviar':'Finalize a tarefa atual para responder'}">${esc(state.chatDraft)}</textarea><div class="compose-actions"><button data-action="paste" ${allowed&&state.clipboard?'':'disabled'}>Colar na mensagem</button><button class="send-message" data-action="send" ${allowed?'':'disabled'}>Enviar para ${tech?'o técnico':'o cliente'} →</button></div>${state.clipboard?`<small class="clipboard-state">✓ ${state.clipboard.kind==='location'?'Localização':'Login e senha'} na área de transferência do jogo</small>`:''}</div></section>`;}
function finishView(){return `<section class="finale"><span class="eyebrow">TODOS OS TESTES APROVADOS / CLIENTE COM ACESSO</span><h2>INSTALAÇÃO CONCLUÍDA<br>COM SUCESSO</h2><p>O cliente já está na rua. Agora é só acompanhar.</p><div class="final-grid"><article class="system-card">${erpHeader('ANDERSON TRACK','Acompanhamento / Veículo liberado')}<div class="monitor-toolbar"><strong>${esc(state.vehicle)}</strong><span class="gps-status green"><i></i>EM MOVIMENTO</span></div><div id="map-slot">${mapSvg(state)}</div><div class="final-map-note"><span>● ATUALIZAÇÃO AUTOMÁTICA</span><span>Anderson · Cliente</span></div></article><aside><div class="praise-card cat-praise">${portrait('cat','happy')}<div><small>CAT / CHEFE DO SETOR</small><strong>AGORA SIM, ANDERSON!</strong><p>Instalou, testou e liberou. Você continua empregado!</p></div></div><div class="praise-card">${portrait('bear',state.phase==='finish'?'happy':'angry')}<div><small>BEAR / CHEFE DA ATIVAÇÃO</small><strong>ISSO É EFICIÊNCIA!</strong><p>Parabéns! Até que enfim alguém acompanha o meu ritmo!</p></div></div><div class="final-thanks">${bubble('Obrigado, Anderson! Recebi a posição e os testes. Cliente liberado.',false,'Anderson · Técnico')}${bubble('O acesso funcionou! Já estou vendo meu veículo. Obrigado!',false,'Anderson · Cliente')}</div><div class="final-checks">✓ Equipamento testado<br>✓ Posição enviada ao técnico<br>✓ Login e senha enviados ao cliente</div></aside></div><div class="final-buttons"><button class="action-primary" data-action="heist">Continuar para O grande roubo →</button><button data-action="menu">Voltar ao início</button><button data-action="new-case">Começar outro expediente →</button></div></section>`;}
function render(focus=false){if(!state)return;document.body.classList.toggle('pressure-active',!['finish','failed'].includes(state.phase));document.body.classList.toggle('reduce-motion',!!context.prefs?.reduceMotion);app.innerHTML=shell(({imei:imeiView,maze:workflowView,platform:platformView,diagnosis:diagnosisView,repairing:repairingView,location:platformView,handoff:workflowView,credentials:credentialsView,finish:()=>''}[state.phase]||(()=>''))());if(state.phase!=='imei'){const el=$('#activation-messages');if(el)el.scrollTop=el.scrollHeight;}if(focus){window.scrollTo(0,0);($('#diagnostic-title')||$('#task-title')||$('#imei')||$('.chapter h1'))?.focus({preventScroll:true});}}
function update(action){if(!state||state.phase==='failed')return;desk?.checkpoint(state);if(action.type==='imei')desk?.record('imei',{imei:true,imeiCorrect:action.value===state.imei});const previous=state.phase,next=applyActivationAction(state,action);if(next===state)return;state=next;if(action.type!=='imei')desk?.record(action.type+':'+(action.id||''),{progress:['workflow','solve-check','send','command','inspect-diagnostic','resolve-diagnosis'].includes(action.type)});if(state.phase==='failed'){fire();return;}save();render(previous!==state.phase||action.type==='workflow');if(previous!==state.phase&&['diagnosis','repairing'].includes(state.phase))notifyTech();audio.play(state.phase==='finish'?'success':'tick');if(state.phase==='finish'){desk?.finish();$('#tech-notification').classList.remove('show');$('#activation-toast').classList.remove('show');clearTimeout(noticeTimer);clearTimeout(toastTimer);tell('complete',{phase:'finish'});}else tell('progress',{phase:state.phase});}
function notifyTech(){if(state.phase==='finish'||state.phase==='failed'||modal.children.length)return;const n=notifications(),text=state.phase==='diagnosis'?'ANDERSON! COMPARE OS TRÊS QUADROS E ESCOLHA A CONDUTA CERTA!':state.phase==='repairing'?'A CONFERÊNCIA ESTÁ SENDO ATUALIZADA. AGUARDE A CONFIRMAÇÃO!':n%2===0?reactiveLine(3,state.phase,desk?.lastAction.split(':')[0],desk?.repeats||0,desk?.pressure||0):PRESSURE[Math.max(0,n-1)%PRESSURE.length],el=$('#tech-notification');el.innerHTML=`<div class="pressure-person"><span class="pressure-avatar">A</span><div><b>ANDERSON · TÉCNICO <em>COBRANÇA #${n+1}</em></b><span class="pressure-message">${text}</span></div></div><div class="pressure-bear">${portrait('bear',state.phase==='finish'?'happy':'angry')}<span id="pressure-bear-line">${BEAR_LINES[Math.floor(state.elapsedMs/7000)%BEAR_LINES.length]}</span></div><small>O TÉCNICO CONTINUA ESPERANDO. O BEAR TAMBÉM.</small>`;el.classList.add('show');if(n>0)audio.play('message');}
function refreshLive(){if(!state||state.phase==='failed')return;const el=$('#elapsed');if(el)el.textContent=elapsed();const phase=$('#current-phase');if(phase)phase.textContent=phaseName(state);const total=$('#notification-total');if(total)total.textContent=notifications();const bear=$('#bear-line');if(bear&&state.phase!=='imei'&&state.phase!=='finish')bear.textContent=desk&&desk.repeats>=3?reactiveLine(3,state.phase,desk.lastAction,desk.repeats,desk.pressure):BEAR_LINES[Math.floor(state.elapsedMs/7000)%BEAR_LINES.length];const bannerBear=$('#pressure-bear-line');if(bannerBear)bannerBear.textContent=BEAR_LINES[Math.floor(state.elapsedMs/7000)%BEAR_LINES.length];const waiting=$('#position-wait');if(waiting)waiting.textContent=`Recebendo posição · ${Math.floor(state.waitMs/1000)} s`;if(state.phase==='finish'){const vehicle=$('#moving-vehicle');if(vehicle&&!context.prefs?.reduceMotion){const p=vehiclePoint(state.finishMs);vehicle.setAttribute('transform',`translate(${p.x} ${p.y}) rotate(${p.angle})`);}}const repair=$('#diagnostic-repair-progress');if(repair)repair.value=state.diagnosis.repairMs;const repairTime=$('#diagnostic-repair-time');if(repairTime)repairTime.textContent=`Atualizando os indicadores · ${Math.ceil((DIAGNOSIS_REPAIR_MS-state.diagnosis.repairMs)/1000)} s`;const count=notifications();if(count>lastPressure&&state.phase!=='finish'){lastPressure=count;const list=$('#activation-messages');if(list){const scroll=list.scrollTop;list.innerHTML=messages();list.scrollTop=state.phase==='imei'?scroll:list.scrollHeight;}if(state.chatTarget==='tech')seen=count;const unread=$('#chat-unread');if(unread)unread.textContent=Math.max(0,count-seen);notifyTech();}}
function tick(){const now=performance.now(),delta=Math.min(1500,Math.max(0,now-lastTick));lastTick=now;if(!state||document.hidden||modal.children.length||state.phase==='failed')return;desk?.step(delta,state.phase,{waiting:state.phase==='repairing'||state.phase==='platform'&&state.commandSent});const previous=state.phase;state=advanceActivation(state,delta);if(previous!==state.phase){if(previous==='repairing')selectedCommand=null;save();render(true);audio.play(state.phase==='diagnosis'?'message':'success');tell('progress',{phase:state.phase});notifyTech();}refreshLive();if(Math.floor(state.elapsedMs/1000)%5===0)save();}
function fire(){desk?.fail();clearInterval(tickId);try{localStorage.removeItem(saveKey());}catch{}tell('failed',{phase:'failed'});audio.play('fail');$('#tech-notification').classList.remove('show');app.inert=true;let seconds=12;modal.innerHTML=`<div class="activation-backdrop"><section class="fired-dialog" role="dialog" aria-modal="true" aria-labelledby="fired-title"><div class="failure-face">${portrait('cat','angry')}</div><div><span class="eyebrow">O BEAR CHAMOU O RECURSOS HUMANOS.</span><h2 id="fired-title">ESTÁ DEMITIDO!</h2><p>${esc(state.failure)}</p>${desk?.retryButton()||''}<button class="action-primary" data-action="menu">Voltar ao início →</button><small>${desk?.canRetry?'A conferência atual foi preservada no checkpoint.':'Contrato de experiência: o expediente acabou.'}</small></div></section></div>`;modal.querySelector('button').focus();if(!desk?.canRetry)failureTimer=setInterval(()=>{seconds--;if($('#failure-seconds'))$('#failure-seconds').textContent=seconds;if(seconds<=0)exit();},1000);}
function exit(event='menu'){save();clearInterval(tickId);clearInterval(failureTimer);if(parent===window)location.href='./';else tell(event);}
function openModal(content,extra=''){focusBefore=document.activeElement;app.inert=true;modal.innerHTML=`<div class="activation-backdrop"><section class="info-dialog ${extra}" role="dialog" aria-modal="true" aria-labelledby="info-title"><header><h2 id="info-title">${extra==='photo-dialog'?'Fotos do técnico':'Como sobreviver ao Ato 3'}</h2><button data-action="close-modal">Fechar</button></header>${content}</section></div>`;modal.querySelector('button').focus();}
function closeModal(){if(state.phase==='failed')return;modal.innerHTML='';app.inert=false;lastTick=performance.now();if(focusBefore?.isConnected)focusBefore.focus({preventScroll:true});}
async function copy(kind){update({type:kind==='location'?'copy-location':'copy-credentials'});if(!state.clipboard)return;toast(kind==='location'?'Localização copiada. Cole no WhatsApp do técnico.':'Login e senha copiados. Envie ao cliente Anderson.');try{await navigator.clipboard?.writeText(state.clipboard.text);}catch{}}
function dispatch(action,id){if(action==='retry-checkpoint')return retryActivation();if(['open-diagnosis','inspect-diagnostic','resolve-diagnosis'].includes(action))return update({type:action,id});if(action==='solve-check')return update({type:'solve-check',id});if(action==='heist'&&state.phase==='finish'){if(parent===window)location.href='./heist.html';else tell('heist');return;}if(action==='menu')return exit();if(action==='new-case')return exit('new-case');if(action==='close-modal')return closeModal();if(action==='help')return openModal('<ol><li>Digite os 15 números do IMEI que aparece na foto do técnico. Você pode ampliar a etiqueta.</li><li>Siga a ordem atual do Bear em cada uma das 20 telas. Os botões mudam de posição. Confirme a ação pelo nome.</li><li>Na plataforma, envie “Solicitar posição atual”. Se houver uma inconsistência, compare Cadastro, Laudo e Telemetria e escolha a conduta correspondente. Aguarde a confirmação e solicite uma nova posição. Sem falha, aguarde a aquisição normal.</li><li>Copie a localização, selecione Anderson · Técnico, cole e envie.</li><li>Conclua as seis telas de acesso. Copie login e senha, selecione Anderson · Cliente, cole e envie.</li></ol><p>Uma ação incorreta encerra o expediente. Ler mensagens, abrir fotos e escolher o contato não contam como erro. O tempo aumenta a pressão; você pode continuar lendo sem um prazo de derrota.</p>');if(action==='photo-equipment')return openModal(equipmentPhoto(state)+'<p>Leia o IMEI da etiqueta do equipamento. Os outros números são S/N e ICCID.</p>','photo-dialog');if(action==='photo-installation')return openModal(installationPhoto(state)+`<p>LT-32 PRO instalado na ${LOCATIONS.find(l=>l.id===state.installationLocation).name.toLowerCase()}.</p>`,'photo-dialog');if(action==='sound'){if(parent===window){context.prefs.sound=context.prefs.sound===false;render();}else tell('sound');return;}if(action==='workflow')return update({type:'workflow',id});if(action==='select-command'){selectedCommand=id;render();return;}if(action==='send-command')return update({type:'command',id:selectedCommand});if(action==='contact'){if(id==='tech')seen=notifications();return update({type:'chat-target',id});}if(action==='copy-location')return copy('location');if(action==='copy-credentials')return copy('credentials');if(action==='paste')return update({type:'paste'});if(action==='send'){const value=$('#chat-draft').value;if(!value.trim()){toast('Cole a informação antes de enviar.');return;}return update({type:'send',target:state.chatTarget,value});}}
for(const root of [app,modal])root.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&!button.disabled){event.preventDefault();dispatch(button.dataset.action,button.dataset.id);}});
app.addEventListener('submit',event=>{if(event.target.id==='imei-form'){event.preventDefault();update({type:'imei',value:$('#imei').value});}});
app.addEventListener('input',event=>{if(!state)return;if(event.target.id==='imei')state.imeiDraft=event.target.value;if(event.target.id==='chat-draft')state.chatDraft=event.target.value;save();});
for(const name of ['paste','drop'])app.addEventListener(name,event=>{if(event.target.id==='imei'){event.preventDefault();toast('O IMEI deve ser digitado manualmente. Confira a foto do técnico.');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.children.length&&state.phase!=='failed'){event.preventDefault();closeModal();return;}if(modal.children.length&&event.key==='Tab'){const list=[...modal.querySelectorAll('button,[href],input')],first=list[0],last=list.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
function initialize(payload){if(state){context={...context,...payload,prefs:payload.prefs||context.prefs};desk?.updateContext(context);render();return;}context={...payload,prefs:payload.prefs||{}};desk=new ShiftSession({act:3,context,tell});let raw=null;try{raw=JSON.parse(localStorage.getItem(saveKey()));}catch{}const retryRaw=desk.pendingRetry&&desk.canRetry?desk.retry():desk.snapshot;state=restoreActivation(raw,context.caseId,context)||restoreActivation(retryRaw,context.caseId,context)||createActivation(context.caseId,context);desk.checkpoint(state);if(state.phase==='finish')desk.finish();lastPressure=notifications();seen=notifications();render();save();tell(state.phase==='finish'?'complete':'progress',{phase:state.phase});lastTick=performance.now();tickId=setInterval(tick,200);notifyTech();}
window.addEventListener('message',event=>{if(event.source===parent&&event.origin===location.origin&&event.data?.type==='andersons-context'&&event.data.payload?.caseId)initialize(event.data.payload);});
window.addEventListener('pagehide',()=>{save();clearInterval(tickId);});document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden){save();audio.ctx?.suspend().catch(()=>{});}else if(context?.prefs?.sound!==false)audio.ctx?.resume().catch(()=>{});});
tell('ready');if(parent===window)initialize({caseId:'activation-solo-'+Date.now().toString(36),mode:'activation-free',prefs:{sound:true,reduceMotion:matchMedia('(prefers-reduced-motion: reduce)').matches}});

function challengeMarkup(){const check=challengeFor(state);if(!check)return '';if(check.solved)return '<section class="activation-check solved"><strong>✓ Dados conferidos. Execute agora a ordem do Bear.</strong></section>';return `<section class="activation-check" aria-label="Conferência de dados"><h3>${check.title}</h3><p>${esc(check.instruction)}</p><div class="activation-check-grid">${check.choices.map(c=>`<button data-action="solve-check" data-id="${c.id}">${esc(c.label)}</button>`).join('')}</div></section>`;}
function retryActivation(){if(!desk?.canRetry)return;const next=restoreActivation(desk.retry(),context.caseId,context);if(!next)return;clearInterval(failureTimer);modal.innerHTML='';app.inert=false;state=next;selectedCommand=null;lastTick=performance.now();render(true);save();tickId=setInterval(tick,200);tell('progress',{phase:state.phase});notifyTech();}
